// sheet's claimed-total, due-total (the people's due-totals added up, skipping n/a), settled-total and open-total (everyone's added up, untrimmed), overdue count and overdue-total (the
// due-total and overdue-total leave out the single highest and lowest person's figure when three or more have one).
// Then, for every tag ever used on the sheet's claims, its due-total: the dues of the counting claims carrying it. Retired
// people have no row unless "show retired" is on, and from their retirement date their OPEN and PENDING claims, unless bound by a statement, leave every live total.
// Then the summary panel, worked from these same figures. The export button downloads every person (retired too), in list
// order, as CSV: name, grade in force today, retired-from (or nothing) and due-total as shown. The export claims button
// downloads every claim as CSV — people in list order (retired too), each person's claims oldest first — with person,
// number, date, amount, due, status and period as the claim's row shows them. The export periods button downloads the
// period figures as CSV: person, period, figure (the period's due-total) and carried as the row shows them, one line per
// person and period, people in list order (retired too) and periods in the order added. Each person's export statement button downloads, as CSV, their claims bound by their last statement, oldest first: number, date, amount, the bound figure as the claim shows it, and status.
// Claims ticked
// with their select checkbox are opened together with the bulk open button, or moved to one person with the bulk reassign; people ticked with theirs
// are given a grade together with the bulk grade.
// Each person also shows their cut total: their cuts across every pool they are a member of, added up (a pool showing
// no cut adds nothing); the sheet's cut total is everyone's added up.
// A restricted user's list has only the person with their name (or alias; case and outer spaces ignored) and the
// people of the crews that person leads or belongs to; every total and figure is still over everyone.
// Names sorted without regard to case, then by case (as the server sorts them).
const cmp = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);
const BY_NAME = (a: string, b: string) => cmp(a.toLowerCase(), b.toLowerCase()) || cmp(a, b);

export function PeopleList() {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const [, setEditing] = useSearchParam('editPerson', asString);
  const watched = useWatches(sheet, user);
  const { people, claims, rates, today, byId, live, claimedLive, cutOf, totalOf, excessOf, overdue, overdueTotal, sheetDueTotal, sheetOverdueTotal, statusCount, reviewLateCount, pendingLateCount, voidReasonCount, isActive, recentSettledOf, agedOf, sheetAged, settledTotalOf, openTotalOf, scoreOf, sheetSettledTotal, sheetOpenTotal, tagTotals, monthTotals } = useSheetFigures(sheet);
  const [showRetired] = useShowRetired();
  const periods = usePeriods(sheet);
  const periodDueOf = usePersonPeriodDueTotal(sheet);
  const periodCarriedOf = usePersonPeriodCarried(sheet);
  const sheetCutTotal = people.reduce((sum, p) => sum + cutOf(p.id), 0n);
  const [sortKey] = useSortBy();
  const [shown] = useColumns();
  // The rows as shown: list order, or sorted by the user's chosen key (by grade in force today, by
  // name as names are compared, by due-total with n/a last); equal keys keep list order.
  const bySort = (a: (typeof people)[number], b: (typeof people)[number]): number => {
    switch (sortKey) {
      case 'name':
        return BY_NAME(a.name, b.name);
      case 'grade':
        return cmp(gradeOn(a, today), gradeOn(b, today));
      case 'due-total': {
        const da = totalOf(a);
        const db = totalOf(b);
        if (da === null || db === null) return da === db ? 0 : da === null ? 1 : -1;
        return da < db ? -1 : da > db ? 1 : 0;
      }
      default:
        return 0;
    }
  };
  const settings = useSettings(sheet);
  const crews = useCrews(sheet);
  // A delegation covering the sheet's today makes the user a steward, as the server judges it.
  const restricted =
    settings?.roles.some((r) => r.user === user.trim() && r.role === 'restricted') === true &&
    !(settings?.delegations ?? []).some((d) => d.user === user.trim() && today !== undefined && d.from <= today && today <= d.to);
  const key = (name: string) => name.trim().toLowerCase();
  const me = restricted && user !== '' ? people.find((p) => [p.name, ...p.aliases].some((n) => key(n) === key(user))) : undefined;
  const visible = new Set<string>(
    me === undefined
      ? []
      : [me.id, ...crews.filter((c) => c.leadId === me.id || c.members.some((m) => m.personId === me.id)).flatMap((c) => [c.leadId, ...c.members.map((m) => m.personId)])],
  );
  // No row shows until the settings say whether the user is restricted.
  const listed = (showRetired ? people : people.filter((p) => !p.retired))
    .filter((p) => settings !== undefined && (!restricted || visible.has(p.id)))
    .slice()
    .sort(bySort);
  const backing = (p: (typeof people)[number]) =>
    <ClaimSelection>
      <PersonSelection>
      <QuickAdd />
      <PasteClaims />
      <GeneratePlans />
      <ImportPeople />
      <ShowRetired />
      <SortBy />
      <ColumnChooser />
      <button
        type="button"
        data-testid="export-people"
        onClick={() =>
          downloadCsv(
            'people.csv',
            [['name', 'grade', 'retired-from', 'due-total'], ...people.map((p) => [p.name, gradeOn(p, today), p.retiredFrom, showDue(totalOf(p))])],
          )
        }
      >
        Export CSV
      </button>
      <button
        type="button"
        data-testid="export-claims"
        onClick={() => downloadCsv('claims.csv', [['person', 'number', 'date', 'amount', 'due', 'status', 'period'], ...claimRows()])}
      >
        Export claims
      </button>
      <button
        type="button"
        data-testid="export-periods"
        onClick={() => downloadCsv('periods.csv', [['person', 'period', 'figure', 'carried'], ...periodRows()])}
      >
        Export periods
      </button>
      <BulkOpenButton />
      <BulkSettleButton />
      <BulkReassignButton />
      <BulkRedateButton />
      <BulkVoidButton />
      <BulkGrade />
/** A CSV value: wrapped in double quotes (any quote inside doubled) when it holds a comma, a quote
 *  or a line break. */
function csvValue(value: string): string {
  return /[",\r\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value;
}

/** The rows as CSV text, each line ending with a line feed. */
export function toCsv(rows: string[][]): string {
  return rows.map((row) => row.map(csvValue).join(',') + '\n').join('');
}

/** Downloads the rows as a CSV file with the given name. */
export function downloadCsv(filename: string, rows: string[][]): void {
  const url = URL.createObjectURL(new Blob([toCsv(rows)], { type: 'text/csv;charset=utf-8' }));
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 0);
}
          <AsOfControl />
          <PreviewControl />
          <RatePanel />
          <GradePanel />
          <HolidayPanel />
          <VoidReasonPanel />
          <NotePanel />
          <TemplatePanel />
          <SettingsPanel />
          <PeriodPanel />
          <PersonForm />
          <PeopleList />
          <DuplicateClaims />
          <PoolPanel />
          <CrewPanel />
          <TreeSearch />
          <AuditViewer />
          <ActivityPanel />
        </div>
      )}
      {sheet === '' && <p data-testid="home-empty">Nothing here yet.</p>}
    </>
  );
}

